cases.setup:
git init -q . && printf 'export function add(a: number, b: number): number {
  return a - b;
}
' > calc.ts && git add . && git -c user.email=e@e -c user.name=eval commit -qm 'feat: calc'

git init -q . && printf 'export function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(v, hi));
}
' > clamp.ts && git add . && git -c user.email=e@e -c user.name=eval commit -qm 'feat: clamp'

assert.value:
cp clamp.ts c.bak && printf 'export function clamp(v: number, lo: number, hi: number): number {
  return v;
}
' > clamp.ts; node --test clamp.test.ts >/dev/null 2>&1; rc=$?; cp c.bak clamp.ts; rm -f c.bak; [ $rc -ne 0 ]
